int out_fd = 5;       // Socket or pipe FD
int in_fd = 3;        // Regular file FD
size_t length = 4096;
ssize_t sent_bytes;

// Transfer from current file offset
sent_bytes = sendfile(out_fd, in_fd, NULL, length);

// Transfer starting at a specific offset
off_t start_offset = 1024;
sent_bytes = sendfile(
    out_fd,
    in_fd,
    &start_offset, // Offset is updated by bytes sent
    length
);
